 function methodReview(v){const issues=[];const add=(title,detail)=>issues.push({title,detail});if(v.aim==='experience'&&v.evidence!=='accounts')add('Experience needs suitable accounts','Use interviews or another justified source of accounts, or revise the aim to describe the numeric records.');if(v.aim==='relationship'&&(!text(v.second).trim()||v.evidence==='accounts'))add('Define two measurable constructs','Specify both constructs and suitable measures. Accounts alone do not estimate a numeric relationship.');if(v.aim==='effect'&&v.evidence==='accounts')add('An effect estimate needs a defined outcome measure','Accounts can illuminate experience or process; explain how the effect outcome will be measured and compared, or revise the aim.');if(v.aim==='effect'&&!['randomized','comparison'].includes(v.design))add('An effect claim needs a defensible comparison','A one-time survey or a change over time does not isolate an intervention effect. Consider a bounded descriptive or feasibility question.');if(v.analysis==='themes'&&v.evidence==='numeric')add('Themes need interpretable qualitative material','Explain the text/accounts and the interpretive process, or choose an analysis suited to the recorded numbers.');if(['correlation','summary'].includes(v.analysis)&&v.evidence==='accounts')add('The proposed numeric analysis needs defined measurements','Use an appropriate qualitative analysis, or justify how constructs will be measured numerically.');if(v.scope==='population'&&v.sampling!=='probability')add('Selection limits population estimates','Describe the sampled setting. Population estimates need a justified selection process and attention to coverage and nonresponse.');if(!text(v.measure).trim())add('Define what will be observed or measured','Name the construct and the actual indicator, instrument or interview focus. A topic label alone does not define a measure.');return issues;}
 function reviewValues(raw){const enums={aim:['experience','describe','relationship','effect'],evidence:['accounts','numeric','both'],design:['interviews','one-time','beforeafter','comparison','randomized'],analysis:['themes','summary','correlation','comparison'],sampling:['convenience','purposeful','probability'],scope:['local','population']},v={};for(const [key,choices]of Object.entries(enums)){if(!choices.includes(raw[key]))throw Error('Choose a valid '+key+'.');v[key]=raw[key];}v.measure=text(raw.measure,1000);v.second=text(raw.second,1000);return v;}
