 function claimReview(value,design='unknown'){const issues=[];if(/\b(prov(?:e|es|en)|caus(?:e|es|ed)|leads? to|results? in|improves?)\b/i.test(value)&&!['experiment','randomized'].includes(design))issues.push('Causal wording detected. Check whether the design supports attribution; an association or account alone does not.');if(/\b(all students|every student|all universities|everyone|always|never)\b/i.test(value))issues.push('Broad wording detected. Explain how the population, selection and setting support this scope.');return issues;}
 function nextStep(p){const w=p.workbench||{},room=(key)=>'#research/'+p.id+'/'+key;if(!p.question?.trim())return {label:'Shape a question you can investigate',why:'Your project does not yet have a recorded question.',href:'#create/question'};if(!p.papers.length)return {label:'Find a source for this question',why:'Start with one relevant study, then inspect its original methods and results.',href:'#create/papers'};if(!p.evidence.length)return {label:'Read one source and capture a useful passage',why:'A saved reference needs an interpretation and a source location before it can support your argument.',href:room('reader')};if(!(w.claims||[]).length)return {label:'Connect a claim to your evidence',why:'You have evidence notes. Explain one contribution and link its supporting or challenging notes.',href:room('claims')};if((w.claims||[]).some(c=>!c.links.length))return {label:'Give an unlinked claim an evidence trail',why:'At least one recorded claim has no evidence link.',href:room('claims')};if(!(w.design||[]).length)return {label:'Plan how your question can be answered',why:'Define the evidence, measure, selection and analysis you will need.',href:room('design')};const gaps=W.alignment(p).find(d=>d.gaps.length);if(gaps)return {label:'Complete the method plan for objective '+gaps.index,why:'Still missing: '+gaps.gaps.join(', ')+'.',href:room('design')};if(!p.proposal.trim())return {label:'Develop a source-linked proposal',why:'Use your recorded claims and methods to explain a bounded plan. Keep uncollected results clearly proposed.',href:room('proposal')};return {label:'Review the reasoning and prepare a handoff',why:'Recorded fields are a starting point. Review the sources, design and boundaries, then keep a portable copy.',href:room('review')};}
 function comparisons(p){return p.papers.map(s=>{const notes=p.evidence.filter(n=>n.paperId===s.id);const join=key=>[...new Set((key==='findings'?notes.filter(n=>!n.readingRole||n.readingRole==='finding'):notes).map(n=>n[key]?.trim()).filter(Boolean))].join('\n');return {source:s.title,paperId:s.id,notes:notes.length,population:join('context')||join('sample'),method:join('method'),finding:join('findings'),limitation:join('limitations'),locations:join('locator')};});}
